import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, rowToJob, JOB_COLUMNS } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
type FieldError = { field: string; message: string };

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
function invalid(res: ServerResponse, fields: FieldError[]): void {
  error(res, 400, 'invalid_request', 'The request is invalid.', fields.length ? fields : [{ field: 'body', message: 'Invalid request.' }]);
}
async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    size += buf.length;
    if (size > 1024 * 1024) throw new Error('body too large');
    chunks.push(buf);
  }
  return Buffer.concat(chunks).toString('utf8');
}

const server = createServer(async (req, res) => {
  let pathname: string;
  try { pathname = new URL(req.url ?? '/', 'http://localhost').pathname; }
  catch { return error(res, 404, 'not_found', 'Route not found.'); }

  if (pathname === '/') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/health') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const heartbeat = db.prepare('SELECT updated_at FROM worker_heartbeat WHERE id=1').get() as { updated_at: number } | undefined;
    return send(res, 200, { status: 'ok', worker: heartbeat && Date.now() - Number(heartbeat.updated_at) < 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (req.method === 'GET') {
      const rows = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs ORDER BY created_at DESC, rowid DESC`).all() as Record<string, unknown>[];
      return send(res, 200, { jobs: rows.map(rowToJob) });
    }
    if (req.method !== 'POST') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const fields: FieldError[] = [];
    const key = req.headers['idempotency-key'];
    const idempotencyKey = Array.isArray(key) ? key[0] : key;
    if (idempotencyKey !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(idempotencyKey)) {
      fields.push({ field: 'Idempotency-Key', message: 'Must contain 1 to 128 letters, digits, underscores, or hyphens.' });
    }
    if ((req.headers['content-type'] ?? '').split(';')[0].trim().toLowerCase() !== 'application/json') {
      fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
      return invalid(res, fields);
    }
    let body: unknown;
    try { body = JSON.parse(await readBody(req)); }
    catch { return invalid(res, [...fields, { field: 'body', message: 'Body must contain valid JSON.' }]); }
    if (!body || typeof body !== 'object' || Array.isArray(body)) {
      fields.push({ field: 'body', message: 'Body must be a JSON object.' });
      return invalid(res, fields);
    }
    const obj = body as Record<string, unknown>;
    for (const name of Object.keys(obj)) if (!['input', 'steps', 'failAttempts'].includes(name)) fields.push({ field: name, message: 'Unknown field.' });
    if (typeof obj.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
    else if (obj.input.length < 1 || obj.input.length > 1000 || obj.input.trim().length === 0) fields.push({ field: 'input', message: 'Must be 1 to 1000 characters and not only whitespace.' });
    let steps = 5; let failAttempts = 0;
    if (Object.hasOwn(obj, 'steps')) {
      if (!Number.isInteger(obj.steps) || Number(obj.steps) < 1 || Number(obj.steps) > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
      else steps = Number(obj.steps);
    }
    if (Object.hasOwn(obj, 'failAttempts')) {
      if (!Number.isInteger(obj.failAttempts) || Number(obj.failAttempts) < 0 || Number(obj.failAttempts) > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
      else failAttempts = Number(obj.failAttempts);
    }
    if (fields.length) return invalid(res, fields);

    const input = obj.input as string;
    const payload = JSON.stringify({ input, steps, failAttempts });
    if (idempotencyKey) {
      const previous = db.prepare(`SELECT i.payload, j.${JOB_COLUMNS.split(', ').join(', j.')} FROM idempotency i JOIN jobs j ON j.id=i.job_id WHERE i.key=?`).get(idempotencyKey) as (Record<string, unknown> & { payload: string }) | undefined;
      if (previous) {
        if (previous.payload !== payload) return error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        return send(res, 200, rowToJob(previous));
      }
    }
    const now = new Date().toISOString(); const id = randomUUID();
    db.exec('BEGIN IMMEDIATE');
    try {
      db.prepare(`INSERT INTO jobs (id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at,available_at) VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0)`).run(id, input, steps, failAttempts, now, now);
      if (idempotencyKey) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(idempotencyKey, payload, id);
      db.exec('COMMIT');
    } catch (e) { db.exec('ROLLBACK'); throw e; }
    const row = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id=?`).get(id) as Record<string, unknown>;
    return send(res, 201, rowToJob(row));
  }
  if (/^\/api\/jobs\/[^/]+$/.test(pathname)) {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    let id: string;
    try { id = decodeURIComponent(pathname.slice('/api/jobs/'.length)); } catch { return error(res, 404, 'not_found', 'Job not found.'); }
    const row = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id=?`).get(id) as Record<string, unknown> | undefined;
    if (!row) return error(res, 404, 'not_found', 'Job not found.');
    return send(res, 200, rowToJob(row));
  }
  return error(res, 404, 'not_found', 'Route not found.');
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
function shutdown(): void { server.close(() => { db.close(); process.exit(0); }); }
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
